import {isExcluded} from './exclude.js';
import {readBounded} from './archive.js';
import {parseRepository} from './repositories.js';
import {repositoryTree} from './hosts.js';

const MAX_FILES = 1200;
const MAX_FILE_BYTES = 1_500_000;
const MAX_TOTAL_BYTES = 25_000_000;
const CONCURRENCY = 6;
let wasmPromise;
let activeRun = 0;
let controller = null;

function messageOf(ex) { return ex instanceof Error ? ex.message : String(ex); }
async function engine() {
  if (!wasmPromise) wasmPromise = (async () => {
    // Generated by wasm-pack. GitHub Actions builds this before publishing Pages.
    const mod = await import('./pkg/tokei_wasm.js');
    const response = await fetch(new URL('./pkg/tokei_wasm_bg.wasm', import.meta.url));
    if (!response.ok) throw Error(`Cannot load Rust tokei Wasm: HTTP ${response.status}`);
    await mod.default({module_or_path: await response.arrayBuffer()});
    return mod;
  })().catch(err => {wasmPromise = null; throw err;});
  return wasmPromise;
}

function analyzeBytes(wasm, bytes, path) {
  // wasm-bindgen transfers a Uint8Array into Wasm memory; Rust tokei parses it.
  const parsed = wasm.count_file(path, bytes);
  if (!parsed) throw Error(`tokei did not recognize: ${path}`);
  return parsed;
}

function looksBinary(bytes) {
  const end = Math.min(bytes.length, 4096);
  for (let i = 0; i < end; i++) if (bytes[i] === 0) return true;
  return false;
}

function assemble(rows, title, detail, warnings, skipped) {
  const langs = Object.create(null);
  const totals = {code: 0, comments: 0, blanks: 0, files: 0};
  for (const row of rows) {
    const entry = langs[row.language] ||= {code: 0, comments: 0, blanks: 0, reports: []};
    for (const key of ['code', 'comments', 'blanks']) {entry[key] += row.stats[key]; totals[key] += row.stats[key]; }
    entry.reports.push({name: row.path, stats: row.stats, embedded: row.embedded});
    totals.files++;
  }
  const result = Object.fromEntries(Object.entries(langs).sort((a,b) => b[1].code - a[1].code));
  for (const val of Object.values(result)) val.reports.sort((a,b) => b.stats.code-a.stats.code);
  result.Total = totals;
  return {title, detail, results: result, warnings, skipped, engine: "Rust tokei 15.0.0 / wasm-bindgen", analyzedAt: new Date().toISOString()};
}

function chooseEntries(entries, warnings, wasm) {
  let totalBytes = 0, skipped = 0;
  const selected = [];
  for (const entry of entries) {
    if (!entry || entry.type !== 'blob' || entry.mode === '120000' || isExcluded(entry.path)) continue;
    if (!wasm.detect_language(entry.path)) continue;
    const size = entry.size || 0;
    if (size > MAX_FILE_BYTES || totalBytes + size > MAX_TOTAL_BYTES || selected.length >= MAX_FILES) {skipped++; continue;}
    selected.push(entry); totalBytes += size;
  }
  if (skipped) warnings.push(`${skipped} source files omitted by size/count limits (max ${MAX_FILES} files, ${(MAX_TOTAL_BYTES/1e6)} MB total, ${MAX_FILE_BYTES/1e6} MB/file).`);
  return {selected, skipped};
}

async function analyzeRepository(input, provider, legacy, run, signal, respond) {
  let repository;
  try {repository = parseRepository(input, provider);}
  catch (error) {
    if (legacy) throw Error('The web app supports public GitHub repositories. Enter a repository root URL or owner/repository.');
    throw error;
  }
  if (legacy) {
    if (repository.provider !== 'github') throw Error('The web app supports public GitHub repositories. Use local files for other sources.');
    if (/^https:/i.test(String(input).trim()) && new URL(input).pathname.replace(/^\/+|\/+$/g, '').split('/').length !== 2) {
      throw Error('Enter a repository root URL: https://github.com/OWNER/REPO');
    }
  }
  const wasm = await engine();
  if (run !== activeRun) return;
  const warnings = [];
  const progress = label => respond('progress', {label, done: 0, total: 0});
  progress('Reading repository information…');
  const {entries, rawURL, detail} = await repositoryTree(repository, signal, warnings, progress);
  if (run !== activeRun || signal.aborted) return;
  const {selected, skipped} = chooseEntries(entries, warnings, wasm);
  if (!selected.length) throw Error('No supported text/source files found.');
  const results = new Array(selected.length);
  const failures = [];
  let done = 0, next = 0, actualBytes = 0;
  respond('progress', {label: 'Downloading and analyzing source files…', done, total: selected.length});
  const thread = async () => {
    while (next < selected.length) {
      if (run !== activeRun || signal.aborted) return;
      const index = next++;
      const entry = selected[index];
      try {
        let data = entry.bytes;
        if (!data) {
          const response = await fetch(rawURL(entry), {signal, credentials: 'omit'});
          if (!response.ok) throw Error(`HTTP ${response.status}`);
          data = response.body ? await readBounded(response.body, MAX_FILE_BYTES, 'Source file', signal) : new Uint8Array();
        }
        if (looksBinary(data)) throw Error('binary file');
        if (actualBytes + data.length > MAX_TOTAL_BYTES) throw Error('total size limit');
        actualBytes += data.length;
        const {language, stats, embedded} = analyzeBytes(wasm, data, entry.path);
        results[index] = {path: entry.path, language, stats, embedded};
      } catch (err) {
        if (signal.aborted) return;
        if (failures.length < 8) failures.push(`${entry.path}: ${messageOf(err)}`);
      }
      done++;
      if (done === selected.length || done % 10 === 0) respond('progress', {label: 'Analyzing files in WebAssembly…', done, total: selected.length});
    }
  };
  await Promise.all(Array.from({length: CONCURRENCY}, () => thread()));
  if (run !== activeRun || signal.aborted) return;
  const omitted = selected.length - results.filter(Boolean).length;
  if (omitted) warnings.push(`Unable to analyze ${omitted} files. Examples: ${failures.join(' · ')}`);
  const output = assemble(results.filter(Boolean), repository.project, detail, warnings, skipped + omitted);
  if (!output.results.Total.files) throw Error('File fetching failed. Check your network connection, repository access, or host rate limits.');
  respond('result', {data: output});
}

async function analyzeLocal(files, run, respond) {
  const wasm = await engine();
  if (run !== activeRun) return;
  const warnings = [];
  const entries = [];
  let totalBytes = 0, skipped = 0;
  for (const record of files) {
    const file = record.file || record;
    const path = record.path || file.webkitRelativePath || file.name;
    if (isExcluded(path) || !wasm.detect_language(path)) continue;
    if (file.size > MAX_FILE_BYTES || totalBytes + file.size > MAX_TOTAL_BYTES || entries.length >= MAX_FILES) {skipped++; continue;}
    totalBytes += file.size;
    entries.push({file, path});
  }
  if (skipped) warnings.push(`${skipped} files omitted by size/count limits.`);
  if (!entries.length) throw Error('No supported source files were selected.');
  const rows = [];
  const failures = [];
  let unreadable = 0;
  for (let i = 0; i < entries.length; i++) {
    if (run !== activeRun) return;
    const {file, path} = entries[i];
    try {
      const bytes = new Uint8Array(await file.arrayBuffer());
      if (run !== activeRun) return;
      if (looksBinary(bytes)) throw Error('binary file');
      const {language, stats, embedded} = analyzeBytes(wasm, bytes, path);
      rows.push({path, language, stats, embedded});
    } catch (err) {
      unreadable++;
      if (failures.length < 8) failures.push(`${path}: ${messageOf(err)}`);
    }
    if (i % 10 === 0 || i === entries.length-1) {
      respond('progress', {label: 'Analyzing local files in WebAssembly…', done: i+1, total: entries.length});
      // Yield so cancel/replacement messages can be handled between batches.
      await new Promise(resolve => setTimeout(resolve, 0));
    }
  }
  if (run !== activeRun) return;
  if (unreadable) warnings.push(`${unreadable} binary or unreadable files omitted. Examples: ${failures.join(' · ')}`);
  if (!rows.length) throw Error('No readable source files were found. Binary files cannot be analyzed.');
  const firstPath = files[0]?.path || files[0]?.webkitRelativePath || '';
  const title = firstPath.includes('/') ? firstPath.split('/')[0] : 'Local files';
  respond('result', {data: assemble(rows, title, null, warnings, skipped + unreadable)});
}

self.addEventListener('message', async (ev) => {
  const {type} = ev.data;
  if (type === 'cancel') { activeRun++; controller?.abort(); return; }
  if (!['github', 'repository', 'local'].includes(type)) return;
  const run = ++activeRun;
  controller?.abort(); controller = new AbortController();
  const respond = (kind, detail = {}) => {
    if (run === activeRun) self.postMessage({type: kind, id: ev.data.id, ...detail});
  };
  try {
    if (type === 'github' || type === 'repository') await analyzeRepository(ev.data.url, ev.data.provider, type === 'github', run, controller.signal, respond);
    else if (type === 'local') await analyzeLocal(ev.data.files || [], run, respond);
  } catch (err) {
    if (run === activeRun) respond('error', {message: messageOf(err)});
  }
});
